#!/usr/bin/env bun
/**
 * generate-extension-registry.ts
 *
 * Codegen step (Sub-Issue F of epic #1264): read the root `extensions.config.ts`
 * and emit one `extensions.generated.ts` per package (server, web, cli). Each
 * generated file carries the MANIFESTS of the configured extensions that declare
 * an entry point for that runtime — the loaders (`<pkg>/src/ext/loader.ts`)
 * resolve each extension's `register` lazily via `manifest.entryPoints.<runtime>()`
 * (A's `HapiExtensionManifest` makes the manifest the sole register-locator).
 *
 * Wired into `bun run build:single-exe` (before `build:web`) and runnable
 * standalone via `bun run gen:extensions`.
 *
 * The output files are COMMITTED (locked contract §5b — `.github/workflows/test.yml`
 * runs typecheck/tests on a fresh checkout with NO codegen step, so the generated
 * files must exist in git). Output is DETERMINISTIC — same `extensions.config.ts`
 * always produces byte-identical files (config order preserved, no timestamps),
 * so a regeneration leaves `git status` clean. `*.generated.*` is prettier- and
 * eslint-ignored, so the emitted style survives untouched.
 *
 * See: issue #1270.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

import type { HapiExtensionManifest } from "@hapi/protocol/ext";
import { enabledExtensions } from "../extensions.config";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");

/** Runtime → output file (relative to repo root). One generated file per package. */
type RuntimeKey = "server" | "web" | "cli";
const RUNTIMES: { key: RuntimeKey; outFile: string }[] = [
  { key: "server", outFile: "server/src/extensions.generated.ts" },
  { key: "web", outFile: "web/src/extensions.generated.ts" },
  { key: "cli", outFile: "cli/src/extensions.generated.ts" },
];

/**
 * Runtime-agnostic metadata registry (issue #2329) — the FOURTH emission target,
 * alongside the three per-runtime files above.
 *
 * Why a fourth file: each per-runtime file carries only the extensions declaring
 * THAT runtime's entry point, so no single package can enumerate the whole set.
 * `GET /api/extension-prefs` is built from the SERVER registry, which is why its
 * payload omits web-only and CLI-only extensions and carries no `requiredAtBuild`
 * flag. The Admin control plane needs all of it, and the server package depends
 * only on `@hapi/protocol` — so `shared/` is the only legal home.
 */
const METADATA_OUT_FILE = "shared/src/extensionsMetadata.generated.ts";

/**
 * Runtime keys in the order emitted into each entry's `runtimes` array. Sorted
 * alphabetically (NOT `RUNTIMES` order) so the emitted array is stable and
 * independent of the per-runtime output ordering above.
 */
const RUNTIME_KEYS_SORTED: readonly RuntimeKey[] = ["cli", "server", "web"];

function toPosix(p: string): string {
  return p.split(sep).join("/");
}

/**
 * Import path (extensionless, POSIX) from a generated file to an extension's
 * `manifest` module, forced relative with a leading `./` for same-dir descendants.
 */
function manifestImportPath(outFileDir: string, extPath: string): string {
  const manifestModule = join(repoRoot, extPath, "manifest");
  const rel = toPosix(relative(outFileDir, manifestModule));
  return rel.startsWith(".") ? rel : `./${rel}`;
}

// Load every configured extension's manifest, preserving `enabledExtensions`
// order (determinism). Empty config → empty list → three empty generated files.
interface LoadedExtension {
  path: string;
  manifest: HapiExtensionManifest;
}
const loaded: LoadedExtension[] = [];
for (const extPath of enabledExtensions) {
  const mod = (await import(join(repoRoot, extPath, "manifest"))) as {
    manifest?: HapiExtensionManifest;
  };
  const manifest = mod.manifest;
  if (!manifest || typeof manifest.id !== "string") {
    throw new Error(
      `[gen:extensions] "${extPath}/manifest.ts" must export a 'manifest' ` +
        "with a string 'id' (HapiExtensionManifest)."
    );
  }
  loaded.push({ path: extPath, manifest });
}

/** Render one package's generated file. Manifests-only (R8: per-runtime filter). */
function renderRuntimeFile(key: RuntimeKey, outFile: string): string {
  const outFileDir = dirname(join(repoRoot, outFile));
  // R8: only extensions that declare THIS runtime's entry point are emitted.
  const entries = loaded.filter(e => e.manifest.entryPoints[key]);

  const importLines = entries.map(
    (e, i) =>
      `import { manifest as manifest${i} } from "${manifestImportPath(
        outFileDir,
        e.path
      )}";`
  );
  const entryLines = entries.map((_e, i) => `  { manifest: manifest${i} },`);

  const lines: string[] = [
    "// This file is generated by scripts/generate-extension-registry.ts. Do not edit by hand.",
    "// Regenerate via `bun run gen:extensions`.",
    "",
    'import type { HapiExtensionManifest } from "@hapi/protocol/ext";',
    ...(importLines.length ? ["", ...importLines] : []),
    "",
    "export interface GeneratedExtensionEntry {",
    "  manifest: HapiExtensionManifest;",
    "}",
    "",
    ...(entries.length
      ? [
          "export const extensions: readonly GeneratedExtensionEntry[] = [",
          ...entryLines,
          "];",
        ]
      : ["export const extensions: readonly GeneratedExtensionEntry[] = [];"]),
    "",
  ];
  return lines.join("\n");
}

/**
 * Render the runtime-agnostic metadata registry (issue #2329).
 *
 * Unlike {@link renderRuntimeFile}, this emits INLINED LITERALS rather than
 * manifest imports — so the file pulls no `entryPoints` thunks, and therefore no
 * extension code, into any consumer's module graph. Its only import is the
 * `ExtensionMetadata` type.
 *
 * Entries are grouped by `manifest.id`: a dual-half extension (e.g.
 * `builtin.git-rpc`, `builtin.scheduler`) ships as TWO directories sharing one
 * logical id, each declaring a single runtime, so their `entryPoints` keys are
 * UNIONED into one entry. First-occurrence order of each id is preserved for
 * determinism (locked contract §5b), matching the three per-runtime files.
 */
function renderMetadataFile(): string {
  const byId = new Map<
    string,
    { manifest: HapiExtensionManifest; runtimes: Set<RuntimeKey> }
  >();
  for (const { manifest } of loaded) {
    let entry = byId.get(manifest.id);
    if (!entry) {
      entry = { manifest, runtimes: new Set<RuntimeKey>() };
      byId.set(manifest.id, entry);
    }
    for (const key of RUNTIME_KEYS_SORTED) {
      if (manifest.entryPoints[key]) entry.runtimes.add(key);
    }
  }

  const entryLines: string[] = [];
  for (const { manifest, runtimes } of byId.values()) {
    const ordered = RUNTIME_KEYS_SORTED.filter(k => runtimes.has(k));
    entryLines.push(
      "  {",
      `    id: ${JSON.stringify(manifest.id)},`,
      `    displayName: ${JSON.stringify(manifest.displayName)},`,
      `    description: ${JSON.stringify(manifest.description)},`,
      `    version: ${JSON.stringify(manifest.version)},`,
      // `defaultEnabled` is a required manifest boolean; `requiredAtBuild` is
      // OPTIONAL, so it is normalized here (absent ⇒ false) to match
      // `ExtensionMetadata`'s non-optional field.
      `    defaultEnabled: ${manifest.defaultEnabled === true},`,
      `    requiredAtBuild: ${manifest.requiredAtBuild === true},`,
      `    runtimes: [${ordered.map(k => JSON.stringify(k)).join(", ")}],`,
      "  },"
    );
  }

  const lines: string[] = [
    "// This file is generated by scripts/generate-extension-registry.ts. Do not edit by hand.",
    "// Regenerate via `bun run gen:extensions`.",
    "",
    'import type { ExtensionMetadata } from "./ext/types";',
    "",
    ...(entryLines.length
      ? [
          "export const extensionsMetadata: readonly ExtensionMetadata[] = [",
          ...entryLines,
          "];",
        ]
      : [
          "export const extensionsMetadata: readonly ExtensionMetadata[] = [];",
        ]),
    "",
  ];
  return lines.join("\n");
}

for (const { key, outFile } of RUNTIMES) {
  const outPath = join(repoRoot, outFile);
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, renderRuntimeFile(key, outFile));
  const count = loaded.filter(e => e.manifest.entryPoints[key]).length;
  console.log(`[gen:extensions] Wrote ${count} extension(s) to ${outFile}`);
}

// Fourth emission (issue #2329): the runtime-agnostic metadata registry. Kept in
// its own pass so the three per-runtime files above are byte-unchanged.
{
  const metadataOutPath = join(repoRoot, METADATA_OUT_FILE);
  mkdirSync(dirname(metadataOutPath), { recursive: true });
  writeFileSync(metadataOutPath, renderMetadataFile());
  const uniqueIds = new Set(loaded.map(e => e.manifest.id)).size;
  console.log(
    `[gen:extensions] Wrote ${uniqueIds} extension(s) to ${METADATA_OUT_FILE}`
  );
}
